import{_ as t,o as n,c as r,a3 as a}from"./chunks/framework.B9qR_F1m.js";const m=JSON.parse('{"title":"Im Cockpit","description":"","frontmatter":{},"headers":[],"relativePath":"dcs/cockpit.md","filePath":"dcs/cockpit.md"}'),d={name:"dcs/cockpit.md"};function i(o,e,s,l,h,c){return n(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="im-cockpit" tabindex="-1">Im Cockpit <a class="header-anchor" href="#im-cockpit" aria-label="Permalink to &quot;Im Cockpit&quot;">​</a></h1><p>Die Mission ist gespeichert und läuft auf dem Server. So kommt das Geplante im Jet an.</p><h2 id="f-16c" tabindex="-1">F-16C <a class="header-anchor" href="#f-16c" aria-label="Permalink to &quot;F-16C&quot;">​</a></h2><p><strong>Cartridge laden</strong></p><ul><li>Mit <strong>AutoLoad</strong> lädt der Jet die Cartridge beim Spawn von selbst.</li><li>Ohne AutoLoad: auf der <strong>DTE-Seite</strong> des MFD laden.</li></ul><p>Danach stehen die Steerpoints im DED und auf dem HSD:</p><table tabindex="0"><thead><tr><th>Was</th><th>Wo im Jet</th></tr></thead><tbody><tr><td>Steerpoints 1–24</td><td>DED, HSD, Route 1–3</td></tr><tr><td>Bullseye</td><td>Steerpoint 25</td></tr><tr><td>Geo Lines</td><td>HSD (Steerpoints 31–55)</td></tr><tr><td>Threats</td><td>HSD-Ringe (Steerpoints 56–70)</td></tr><tr><td>DEST</td><td>Steerpoints 81–99</td></tr><tr><td>VIP/VRP</td><td>DED-Seiten VIP und VRP</td></tr><tr><td>Funk</td><td>UHF/VHF-Presets</td></tr><tr><td>CMDS</td><td>nur wenn <em>überschreiben</em> an war – sonst bleiben deine Programme</td></tr></tbody></table><h2 id="f-a-18c" tabindex="-1">F/A-18C <a class="header-anchor" href="#f-a-18c" aria-label="Permalink to &quot;F/A-18C&quot;">​</a></h2><ul><li>AutoLoad oder auf der <strong>MUMI-Seite</strong> laden.</li><li>Waypoints in Route 1, CAP-Punkte, FLOT/FAOR und MEZ-Ringe auf der <strong>SA-Seite</strong>.</li><li>Kanalnamen auf dem <strong>UFC</strong>.</li></ul><h2 id="kneeboard" tabindex="-1">Kneeboard <a class="header-anchor" href="#kneeboard" aria-label="Permalink to &quot;Kneeboard&quot;">​</a></h2><p>Taste <kbd>K</kbd> öffnet das Kneeboard, <kbd>[</kbd> und <kbd>]</kbd> blättern. In der Mission eingebettete Seiten liegen beim jeweiligen Flugzeugtyp: Index, Lineup Cards, Comm Cards, Routenkarten, Attack Cards und die Paket-Kneeboards.</p><p>Tipp: Die Seite <strong>Index</strong> listet alle Flights mit den Seitenzahlen ihrer Lineup Cards – so findet jeder schnell seine.</p><h2 id="f10-karte" tabindex="-1">F10-Karte <a class="header-anchor" href="#f10-karte" aria-label="Permalink to &quot;F10-Karte&quot;">​</a></h2><ul><li><strong>Zeichnungen</strong> erscheinen nach ihrer Ebene (Blue sehen nur Blaue, Common alle).</li><li><strong>Threat-Ringe</strong> nur bei Bedrohungen, die für alle Flights freigegeben sind und bei denen „Auf der F10-Karte zeigen“ an ist.</li></ul><h2 id="wenn-etwas-nicht-stimmt" tabindex="-1">Wenn etwas nicht stimmt <a class="header-anchor" href="#wenn-etwas-nicht-stimmt" aria-label="Permalink to &quot;Wenn etwas nicht stimmt&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Problem</th><th>Prüfen</th></tr></thead><tbody><tr><td>Cartridge erscheint nicht</td><td>Hängt sie am richtigen Flugzeug (DTC-Editor → <em>an …</em>)? Mission nach dem Speichern neu geladen?</td></tr><tr><td>Meine CMDS sind weg</td><td>War bei CMDS <em>überschreiben</em> an? Standard ist aus.</td></tr><tr><td>Elevation passt nicht</td><td><strong>Elev = Boden</strong> nutzt SRTM-Daten; DCS kann um ein paar Meter abweichen.</td></tr><tr><td>TOS um Stunden verschoben</td><td>Zeitzone der Karte prüfen (oben <strong>UTC±</strong>).</td></tr><tr><td>Kneeboard-Seiten fehlen</td><td>Wurden sie <strong>eingebettet</strong> (nicht nur als PNG gespeichert)? Für den richtigen Flugzeugtyp?</td></tr></tbody></table><p>Weitere Antworten: <a href="/referenz/faq">Fragen &amp; Probleme</a>.</p>',17)])])}const b=t(d,[["render",i]]);export{m as __pageData,b as default};
